package db

import (
	"context"
	"database/sql"
	"time"

	"savvy-go/internal/db/sqlc"
	"savvy-go/internal/money"
)

// Q returns typed queries for a database or transaction. Generated by
// `go generate ./internal/db`.
func Q(conn sqlc.DBTX) *sqlc.Queries {
	return sqlc.New(conn)
}

// NInt and NString are nullable columns as sqlc hands them out. Scan targets
// in business code use these so only this package imports database/sql.
type (
	NInt    = sql.NullInt64
	NString = sql.NullString
)

// MoneyFromNull reads a nullable stored amount; nil when NULL.
func MoneyFromNull(v sql.NullInt64, unit money.Unit) *money.Money {
	if !v.Valid {
		return nil
	}
	m := money.New(v.Int64, unit)
	return &m
}

// NullMoney is the stored form of an optional amount.
func NullMoney(m *money.Money) sql.NullInt64 {
	if m == nil {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: m.Minor(), Valid: true}
}

// ErrNotFound is what a single-row lookup returns when there is no such row.
// Business code compares against it, so it never needs database/sql.
var ErrNotFound = sql.ErrNoRows

func NullString(s *string) sql.NullString {
	if s == nil {
		return sql.NullString{}
	}
	return sql.NullString{String: *s, Valid: true}
}

func NullStringVal(s string) sql.NullString {
	if s == "" {
		return sql.NullString{}
	}
	return sql.NullString{String: s, Valid: true}
}

func NullInt64(v *int64) sql.NullInt64 {
	if v == nil {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: *v, Valid: true}
}

// NullInt64If set treats 0 as unset (optional filter IDs).
func NullInt64If(v int64) sql.NullInt64 {
	if v == 0 {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: v, Valid: true}
}

func NullInt(v *int) sql.NullInt64 {
	if v == nil {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: int64(*v), Valid: true}
}

func BoolInt(v bool) int64 {
	if v {
		return 1
	}
	return 0
}

// NS wraps a non-empty timestamp or text value as a valid NullString.
func NS(s string) sql.NullString {
	return sql.NullString{String: s, Valid: true}
}

// NI wraps an id as a valid NullInt64 (for nullable FK columns).
func NI(v int64) sql.NullInt64 {
	return sql.NullInt64{Int64: v, Valid: true}
}

// Flag is 1 when v is true, unset otherwise (sqlc optional filters).
func Flag(v bool) sql.NullInt64 {
	if !v {
		return sql.NullInt64{}
	}
	return sql.NullInt64{Int64: 1, Valid: true}
}

// Narg is an optional text filter: empty means unset (sqlc COALESCE/narg).
func Narg(s string) sql.NullString {
	return NullStringVal(s)
}

// FormatTime is how the app writes a timestamp into a text column.
func FormatTime(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }

// TimeNS wraps a timestamp as a valid NullString.
func TimeNS(t time.Time) sql.NullString { return NS(FormatTime(t)) }

// NullTime wraps an optional timestamp: nil is NULL.
func NullTime(t *time.Time) sql.NullString {
	if t == nil {
		return sql.NullString{}
	}
	return TimeNS(*t)
}

// ParseTime reads a stored nullable timestamp; see ParseTimeString.
func ParseTime(raw sql.NullString) (t time.Time, ok bool) {
	if !raw.Valid {
		return time.Time{}, false
	}
	return ParseTimeString(raw.String)
}

// ParseTimeString reads a stored timestamp: RFC 3339, or the "2006-01-02
// 15:04:05" form SQLite's CURRENT_TIMESTAMP writes (UTC). ok is false for an
// empty or unreadable value.
func ParseTimeString(raw string) (t time.Time, ok bool) {
	if raw == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02 15:04:05"} {
		if t, err := time.ParseInLocation(layout, raw, time.UTC); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

// Ping checks that the database answers.
func Ping(ctx context.Context, conn sqlc.DBTX) error {
	var one int
	return conn.QueryRowContext(ctx, "SELECT 1").Scan(&one)
}
